+fn a_taper_posts_as_a_four_axis_program_with_tp_tn_and_uv_on_every_move() {
+    let out = run(&tapered("Setup1", &[]), &height(5.0));
+    assert!(out.warnings.is_empty(), "{:?}", out.warnings);
+    assert_eq!(
