+        [
+            "G90", "G54", "G00 X-22. Y10. U0. V0.", "Z0.", "T91", "T84", "T94", "C001", "TP5.", "TN25.", "G74",
+            "G01 X-24.5 Y10. U1. V0.", "G01 X-24.5 Y-10. U1. V0.", "G01 X-22. Y10. U0. V0.", "G75", "T90", "M02",
+        ],
